const crypto = require('crypto');

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedHashes) {
  staticData.processedHashes = {};
}

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryKey = (item.binary && typeof item.binary === 'object') ? Object.keys(item.binary)[0] : null;
  if (!binaryKey) {
    results.push({ json: { ...item.json, skip: true, reason: 'no binary data' } });
    continue;
  }

  const binary = item.binary[binaryKey];
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);
  const hash = crypto.createHash('sha256').update(buffer).digest('hex');
  const fileName = item.json.fileName || binary.fileName || 'unknown';

  if (staticData.processedHashes[hash]) {
    results.push({
      json: { ...item.json, file_hash: hash, file_name: fileName, skip: true, reason: 'already processed' }
    });
    continue;
  }

  // Optimistic store: persist hash before ingestion so dedup survives
  // even if downstream HTTP nodes discard item fields (fullResponse).
  // If ingestion fails, the file is skipped on next run. Clear
  // staticData.processedHashes to force re-processing.
  staticData.processedHashes[hash] = new Date().toISOString();

  results.push({
    json: { ...item.json, file_hash: hash, file_name: fileName },
    binary: item.binary
  });
}

return results;

const MAX_POLLS = 60; // 5 minutes at 5-second intervals
const staticData = $getWorkflowStaticData('node');
staticData.pollCount = (staticData.pollCount || 0) + 1;

const items = $input.all();

if (staticData.pollCount > MAX_POLLS) {
  staticData.pollCount = 0;
  return items.map(item => ({
    json: {
      ...item.json,
      status: 'timeout',
      error_message: `Poll timeout after ${MAX_POLLS * 5}s`
    }
  }));
}

// Reset counter when job finishes (status != processing)
if (items[0]?.json?.status !== 'processing') {
  staticData.pollCount = 0;
}

return items;

const items = $input.all();
const results = [];

for (const item of items) {
  const status = item.json.status || item.json.body?.status || 'unknown';
  const docId = item.json.document_id || item.json.body?.document_id || 'unknown';
  const chunks = item.json.chunk_count || item.json.body?.chunk_count || 0;
  const error = item.json.error_message || item.json.body?.error?.message || null;

  // file_name may be lost after HTTP nodes (fullResponse overwrites json),
  // so fall back to Hash & Dedup Check node output.
  let fileName = item.json.file_name;
  if (!fileName) {
    try { fileName = $('Hash & Dedup Check').item.json.file_name; } catch (e) {}
  }
  fileName = fileName || 'unknown';

  const message = (status === 'failed' || status === 'timeout')
    ? `FAILED: ${fileName} - ${error || 'Unknown error'}`
    : `Ingested: ${fileName} (${docId}), ${chunks} chunks, status: ${status}`;

  results.push({
    json: {
      message,
      document_id: docId,
      chunk_count: chunks,
      status,
      file_name: fileName,
      error
    }
  });
}

return results;
